<div class="page-head"><div><span class="hand-label">Point of Sale</span><h2>POS / Buat Order</h2><p>Dine-in, takeaway, delivery, customer, modifier, promo, dan split bill.</p></div></div><div class="pos-layout"><div class="panel"><div class="toolbar"><input class="control" id="menuSearch" placeholder="Cari menu..."><select class="control" id="menuCategory"><option value="">Semua kategori</option></select></div><div class="menu-grid" id="posMenuGrid"></div></div><div class="panel cart-panel"><div class="panel-head"><h3>Bill Baru</h3><button class="text-btn danger" id="clearCart">Kosongkan</button></div><div class="form-grid"><label>Tipe<select class="control" id="orderType"><option value="dine_in">Dine In</option><option value="takeaway">Take Away</option><option value="delivery">Delivery</option></select></label><label>Meja<select class="control" id="orderTable"><option value="">Tanpa meja</option></select></label><label>Customer<select class="control" id="orderCustomer"><option value="">Guest / Tidak terdaftar</option></select></label><label>Jumlah Tamu<input class="control" id="guestCount" type="number" min="1" value="1"></label><label class="span-2">Nama Pelanggan<input class="control" id="customerName" placeholder="Guest"></label><label class="span-2 delivery-only" style="display:none">Alamat Delivery<textarea class="control" id="deliveryAddress"></textarea></label></div><div id="cartItems" class="cart-list"></div><div class="bill-summary"><div><span>Subtotal</span><strong id="cartSubtotal">Rp 0</strong></div><div><span>Diskon Manual</span><input class="control compact" id="discountAmount" type="number" min="0" value="0"></div><div><span>Kode Promo</span><input class="control compact" id="promoCode" placeholder="WELCOME10"></div><div class="bill-total"><span>Total estimasi*</span><strong id="cartTotal">Rp 0</strong></div><small class="muted">*Tax/service dihitung server sesuai pengaturan.</small></div><button class="btn primary full" id="submitOrderBtn">Kirim Order</button></div></div><div class="panel section-gap"><div class="panel-head"><h3>Order Aktif</h3><button class="btn sm outline" id="refreshActiveOrders">Refresh</button></div><div id="activeOrderList"></div></div>
